        sort_time: "2026-08-29 19:30:00",
        end_time_formatted: "2026-08-29 23:59",
        detail: "Get your down-and-dirty slide guitar blues fix with Atlanta-based musician Tinsley Ellis. Ellis, known for decades as one of the greatest electric blues-rock guitarists of his generation, is now also recognized as one of the best contemporary acoustic blues guitarists, songwriters, and performers in the world. \n\nTinsley Ellis’s style of blues is edgy, gritty, foot-stompin\' southern blues.\nEllis’s main influences are Muddy Waters, B.B. King, Howlin’ Wolf. When he was a teenager, Ellis received a broken guitar string from B.B. King that he has to this day. \nRolling Stone describes Tinsley Ellis’s career as “feral blues guitar…non-stop gigging has sharpened his six-string to a razor’s edge…his eloquence dazzles…he achieves pyrotechnics that rival Jeff Beck and Eric Clapton.”",
